insert into public.doing_helper_knowledge_entries
  (knowledge_key, version, category, title, content, keywords, source_type, source_ref, approval_status, is_public, created_by, approved_by, published_at)
values
  ('consumer_faq_001',1,'scope','DOING 可以做什麼？','DOING 可協助找活動或服務、報名／預約、查看審核與候補、付款、通知、改期退款及現場報到。若你要經營活動、課程或預約服務，也可從首頁申請營運帳號。',array['DOING 可以做什麼？','DOING 可以協助哪些事情？','功能','第一次使用','找活動','報名預約'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_002',1,'scope','這個網站有哪些功能？','DOING 可協助找活動或服務、報名／預約、查看審核與候補、付款、通知、改期退款及現場報到。若你要經營活動、課程或預約服務，也可從首頁申請營運帳號。',array['這個網站有哪些功能？','DOING 可以協助哪些事情？','功能','第一次使用','找活動','報名預約'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_003',1,'scope','DOING 能幫我完成什麼？','DOING 可協助找活動或服務、報名／預約、查看審核與候補、付款、通知、改期退款及現場報到。若你要經營活動、課程或預約服務，也可從首頁申請營運帳號。',array['DOING 能幫我完成什麼？','DOING 可以協助哪些事情？','功能','第一次使用','找活動','報名預約'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_004',1,'scope','第一次使用 DOING 要從哪裡開始？','DOING 可協助找活動或服務、報名／預約、查看審核與候補、付款、通知、改期退款及現場報到。若你要經營活動、課程或預約服務，也可從首頁申請營運帳號。',array['第一次使用 DOING 要從哪裡開始？','DOING 可以協助哪些事情？','功能','第一次使用','找活動','報名預約'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_005',1,'workflow','我要去哪裡找活動？','可在首頁搜尋活動、課程、體驗或地點，也可使用快速分類。搜尋結果會直接顯示在搜尋區下方，選擇內容後再查看完整資訊。',array['我要去哪裡找活動？','怎麼找適合的活動？','搜尋','活動','課程','體驗','地點'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_006',1,'workflow','可以用地點搜尋活動嗎？','可在首頁搜尋活動、課程、體驗或地點，也可使用快速分類。搜尋結果會直接顯示在搜尋區下方，選擇內容後再查看完整資訊。',array['可以用地點搜尋活動嗎？','怎麼找適合的活動？','搜尋','活動','課程','體驗','地點'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_007',1,'workflow','如何搜尋課程或體驗？','可在首頁搜尋活動、課程、體驗或地點，也可使用快速分類。搜尋結果會直接顯示在搜尋區下方，選擇內容後再查看完整資訊。',array['如何搜尋課程或體驗？','怎麼找適合的活動？','搜尋','活動','課程','體驗','地點'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_008',1,'workflow','首頁搜尋框要怎麼用？','可在首頁搜尋活動、課程、體驗或地點，也可使用快速分類。搜尋結果會直接顯示在搜尋區下方，選擇內容後再查看完整資訊。',array['首頁搜尋框要怎麼用？','怎麼找適合的活動？','搜尋','活動','課程','體驗','地點'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_009',1,'workflow','第一次要怎麼報名？','先從首頁選擇活動或可預約內容，進入公開頁後按畫面上的報名／預約按鈕，完成場次、個人資料與必要選項後送出。送出後可從「我的報名」查看進度。',array['第一次要怎麼報名？','第一次怎麼報名或預約？','第一次報名','預約步驟','參加活動','報名按鈕'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_010',1,'workflow','預約服務的步驟是什麼？','先從首頁選擇活動或可預約內容，進入公開頁後按畫面上的報名／預約按鈕，完成場次、個人資料與必要選項後送出。送出後可從「我的報名」查看進度。',array['預約服務的步驟是什麼？','第一次怎麼報名或預約？','第一次報名','預約步驟','參加活動','報名按鈕'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_011',1,'workflow','看到喜歡的活動要怎麼參加？','先從首頁選擇活動或可預約內容，進入公開頁後按畫面上的報名／預約按鈕，完成場次、個人資料與必要選項後送出。送出後可從「我的報名」查看進度。',array['看到喜歡的活動要怎麼參加？','第一次怎麼報名或預約？','第一次報名','預約步驟','參加活動','報名按鈕'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_012',1,'workflow','從活動頁要按哪裡報名？','先從首頁選擇活動或可預約內容，進入公開頁後按畫面上的報名／預約按鈕，完成場次、個人資料與必要選項後送出。送出後可從「我的報名」查看進度。',array['從活動頁要按哪裡報名？','第一次怎麼報名或預約？','第一次報名','預約步驟','參加活動','報名按鈕'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_013',1,'workflow','報名送出後怎麼知道成功？','送出後畫面會顯示完成訊息，「我的報名」也會出現同一筆紀錄與目前狀態。若沒有紀錄，先重新整理確認，不要立刻重複送出。',array['報名送出後怎麼知道成功？','怎麼確認報名有成功？','報名成功','送出完成','系統收到','不要重複送出'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_014',1,'workflow','我有沒有報名成功？','送出後畫面會顯示完成訊息，「我的報名」也會出現同一筆紀錄與目前狀態。若沒有紀錄，先重新整理確認，不要立刻重複送出。',array['我有沒有報名成功？','怎麼確認報名有成功？','報名成功','送出完成','系統收到','不要重複送出'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_015',1,'workflow','送出後沒看到畫面怎麼辦？','送出後畫面會顯示完成訊息，「我的報名」也會出現同一筆紀錄與目前狀態。若沒有紀錄，先重新整理確認，不要立刻重複送出。',array['送出後沒看到畫面怎麼辦？','怎麼確認報名有成功？','報名成功','送出完成','系統收到','不要重複送出'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_016',1,'workflow','怎麼確認系統有收到報名？','送出後畫面會顯示完成訊息，「我的報名」也會出現同一筆紀錄與目前狀態。若沒有紀錄，先重新整理確認，不要立刻重複送出。',array['怎麼確認系統有收到報名？','怎麼確認報名有成功？','報名成功','送出完成','系統收到','不要重複送出'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_017',1,'workflow','我的報名在哪裡？','按首頁上方「我的報名」，使用本人的 LINE 登入後，即可查看自己的報名／預約、審核、付款、位置、改期退款與行前資訊。',array['我的報名在哪裡？','報名後去哪裡看紀錄？','我的報名','報名進度','報名紀錄','預約紀錄'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_018',1,'workflow','要去哪裡查報名進度？','按首頁上方「我的報名」，使用本人的 LINE 登入後，即可查看自己的報名／預約、審核、付款、位置、改期退款與行前資訊。',array['要去哪裡查報名進度？','報名後去哪裡看紀錄？','我的報名','報名進度','報名紀錄','預約紀錄'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_019',1,'workflow','怎麼看以前的報名紀錄？','按首頁上方「我的報名」，使用本人的 LINE 登入後，即可查看自己的報名／預約、審核、付款、位置、改期退款與行前資訊。',array['怎麼看以前的報名紀錄？','報名後去哪裡看紀錄？','我的報名','報名進度','報名紀錄','預約紀錄'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_020',1,'workflow','預約完成後在哪裡查看？','按首頁上方「我的報名」，使用本人的 LINE 登入後，即可查看自己的報名／預約、審核、付款、位置、改期退款與行前資訊。',array['預約完成後在哪裡查看？','報名後去哪裡看紀錄？','我的報名','報名進度','報名紀錄','預約紀錄'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_021',1,'application','不登入可以報名嗎？','LINE 登入用來確認是本人並讓你查看自己的報名、付款與行前紀錄。請使用本人的 LINE，不要共用他人的登入身分。',array['不登入可以報名嗎？','為什麼需要 LINE 登入？','LINE 登入','本人','身分','查看紀錄'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_022',1,'application','為什麼我的報名要用 LINE？','LINE 登入用來確認是本人並讓你查看自己的報名、付款與行前紀錄。請使用本人的 LINE，不要共用他人的登入身分。',array['為什麼我的報名要用 LINE？','為什麼需要 LINE 登入？','LINE 登入','本人','身分','查看紀錄'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_023',1,'application','可以用別人的 LINE 報名嗎？','LINE 登入用來確認是本人並讓你查看自己的報名、付款與行前紀錄。請使用本人的 LINE，不要共用他人的登入身分。',array['可以用別人的 LINE 報名嗎？','為什麼需要 LINE 登入？','LINE 登入','本人','身分','查看紀錄'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_024',1,'application','LINE 登入是做什麼用的？','LINE 登入用來確認是本人並讓你查看自己的報名、付款與行前紀錄。請使用本人的 LINE，不要共用他人的登入身分。',array['LINE 登入是做什麼用的？','為什麼需要 LINE 登入？','LINE 登入','本人','身分','查看紀錄'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_025',1,'application','第一次使用要填什麼？','第一次使用會請你完成姓名與必要聯絡資料；完成後，後續符合條件的報名可帶入基本資料，仍要在送出前確認內容。',array['第一次使用要填什麼？','第一次登入要填哪些資料？','第一次登入','會員資料','基本資料','自動帶入'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_026',1,'application','會員資料只要填一次嗎？','第一次使用會請你完成姓名與必要聯絡資料；完成後，後續符合條件的報名可帶入基本資料，仍要在送出前確認內容。',array['會員資料只要填一次嗎？','第一次登入要填哪些資料？','第一次登入','會員資料','基本資料','自動帶入'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_027',1,'application','之後報名還要重填姓名嗎？','第一次使用會請你完成姓名與必要聯絡資料；完成後，後續符合條件的報名可帶入基本資料，仍要在送出前確認內容。',array['之後報名還要重填姓名嗎？','第一次登入要填哪些資料？','第一次登入','會員資料','基本資料','自動帶入'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_028',1,'application','基本資料可以自動帶入嗎？','第一次使用會請你完成姓名與必要聯絡資料；完成後，後續符合條件的報名可帶入基本資料，仍要在送出前確認內容。',array['基本資料可以自動帶入嗎？','第一次登入要填哪些資料？','第一次登入','會員資料','基本資料','自動帶入'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_029',1,'support','一直無法用 LINE 登入怎麼辦？','先關閉登入視窗再重新操作，並確認瀏覽器沒有封鎖跳轉。仍失敗時，請告訴 DOING 客服所在畫面與提示文字；不要在對話中提供密碼或驗證碼。',array['一直無法用 LINE 登入怎麼辦？','LINE 登入失敗怎麼辦？','登入失敗','卡住','錯誤訊息','瀏覽器'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_030',1,'support','LINE 登入畫面卡住了','先關閉登入視窗再重新操作，並確認瀏覽器沒有封鎖跳轉。仍失敗時，請告訴 DOING 客服所在畫面與提示文字；不要在對話中提供密碼或驗證碼。',array['LINE 登入畫面卡住了','LINE 登入失敗怎麼辦？','登入失敗','卡住','錯誤訊息','瀏覽器'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_031',1,'support','登入後又回到首頁','先關閉登入視窗再重新操作，並確認瀏覽器沒有封鎖跳轉。仍失敗時，請告訴 DOING 客服所在畫面與提示文字；不要在對話中提供密碼或驗證碼。',array['登入後又回到首頁','LINE 登入失敗怎麼辦？','登入失敗','卡住','錯誤訊息','瀏覽器'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_032',1,'support','登入出現錯誤訊息要怎麼處理？','先關閉登入視窗再重新操作，並確認瀏覽器沒有封鎖跳轉。仍失敗時，請告訴 DOING 客服所在畫面與提示文字；不要在對話中提供密碼或驗證碼。',array['登入出現錯誤訊息要怎麼處理？','LINE 登入失敗怎麼辦？','登入失敗','卡住','錯誤訊息','瀏覽器'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_033',1,'workflow','可以幫朋友報名嗎？','是否能替同行者報名，要看該活動是否提供人數或成員欄位。請依報名頁顯示填寫；若活動要求每人各自驗證，就要由每位參加者本人完成。',array['可以幫朋友報名嗎？','可以替別人一起報名嗎？','同行者','朋友','親子','團體報名'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_034',1,'workflow','親子活動可以一次填兩個人嗎？','是否能替同行者報名，要看該活動是否提供人數或成員欄位。請依報名頁顯示填寫；若活動要求每人各自驗證，就要由每位參加者本人完成。',array['親子活動可以一次填兩個人嗎？','可以替別人一起報名嗎？','同行者','朋友','親子','團體報名'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_035',1,'workflow','團體報名要怎麼填？','是否能替同行者報名，要看該活動是否提供人數或成員欄位。請依報名頁顯示填寫；若活動要求每人各自驗證，就要由每位參加者本人完成。',array['團體報名要怎麼填？','可以替別人一起報名嗎？','同行者','朋友','親子','團體報名'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_036',1,'workflow','同行者需要各自登入嗎？','是否能替同行者報名，要看該活動是否提供人數或成員欄位。請依報名頁顯示填寫；若活動要求每人各自驗證，就要由每位參加者本人完成。',array['同行者需要各自登入嗎？','可以替別人一起報名嗎？','同行者','朋友','親子','團體報名'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_037',1,'workflow','我好像送出兩次報名','先到「我的報名」確認是否已有同一活動紀錄。若不小心送出兩筆，不要再付款，請聯絡該活動主辦確認要保留哪一筆。',array['我好像送出兩次報名','重複報名怎麼辦？','重複報名','兩筆紀錄','重複送出','不要付款'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_038',1,'workflow','同一活動出現兩筆紀錄','先到「我的報名」確認是否已有同一活動紀錄。若不小心送出兩筆，不要再付款，請聯絡該活動主辦確認要保留哪一筆。',array['同一活動出現兩筆紀錄','重複報名怎麼辦？','重複報名','兩筆紀錄','重複送出','不要付款'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
