  ('consumer_faq_067',1,'billing','已付款還能取消嗎？','先到「我的報名」打開該筆紀錄；尚未付款且畫面有取消入口時可依提示取消。已付款或沒有取消按鈕時，請聯絡該活動主辦依公告規則處理。',array['已付款還能取消嗎？','怎麼取消報名？','取消報名','不參加','已付款取消','取消按鈕'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_068',1,'billing','沒有取消按鈕怎麼辦？','先到「我的報名」打開該筆紀錄；尚未付款且畫面有取消入口時可依提示取消。已付款或沒有取消按鈕時，請聯絡該活動主辦依公告規則處理。',array['沒有取消按鈕怎麼辦？','怎麼取消報名？','取消報名','不參加','已付款取消','取消按鈕'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_069',1,'billing','預約時間可以改嗎？','請到「我的報名」查看是否有改期入口與可選時段；沒有入口或已付款時，請聯絡該活動主辦。改期是否可用及相關費用以該內容公告為準。',array['預約時間可以改嗎？','怎麼改期或換時段？','改期','換時段','選錯日期','改期費用'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_070',1,'billing','要怎麼換活動場次？','請到「我的報名」查看是否有改期入口與可選時段；沒有入口或已付款時，請聯絡該活動主辦。改期是否可用及相關費用以該內容公告為準。',array['要怎麼換活動場次？','怎麼改期或換時段？','改期','換時段','選錯日期','改期費用'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_071',1,'billing','選錯日期可以修改嗎？','請到「我的報名」查看是否有改期入口與可選時段；沒有入口或已付款時，請聯絡該活動主辦。改期是否可用及相關費用以該內容公告為準。',array['選錯日期可以修改嗎？','怎麼改期或換時段？','改期','換時段','選錯日期','改期費用'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_072',1,'billing','改期會不會收費？','請到「我的報名」查看是否有改期入口與可選時段；沒有入口或已付款時，請聯絡該活動主辦。改期是否可用及相關費用以該內容公告為準。',array['改期會不會收費？','怎麼改期或換時段？','改期','換時段','選錯日期','改期費用'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_073',1,'billing','已付款要怎麼退款？','先打開「我的報名」確認該筆紀錄與取消規則，再依畫面操作或聯絡活動主辦。退款資格、金額、手續費與時間由該活動公告及正式紀錄決定，小幫手不會自行承諾。',array['已付款要怎麼退款？','退款要怎麼申請？','退款','退費時間','全額退費','手續費'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_074',1,'billing','退款多久會收到？','先打開「我的報名」確認該筆紀錄與取消規則，再依畫面操作或聯絡活動主辦。退款資格、金額、手續費與時間由該活動公告及正式紀錄決定，小幫手不會自行承諾。',array['退款多久會收到？','退款要怎麼申請？','退款','退費時間','全額退費','手續費'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_075',1,'billing','取消後會全額退費嗎？','先打開「我的報名」確認該筆紀錄與取消規則，再依畫面操作或聯絡活動主辦。退款資格、金額、手續費與時間由該活動公告及正式紀錄決定，小幫手不會自行承諾。',array['取消後會全額退費嗎？','退款要怎麼申請？','退款','退費時間','全額退費','手續費'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_076',1,'billing','退款手續費怎麼算？','先打開「我的報名」確認該筆紀錄與取消規則，再依畫面操作或聯絡活動主辦。退款資格、金額、手續費與時間由該活動公告及正式紀錄決定，小幫手不會自行承諾。',array['退款手續費怎麼算？','退款要怎麼申請？','退款','退費時間','全額退費','手續費'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_077',1,'support','沒收到錄取通知','先到「我的報名」確認最新狀態，再檢查垃圾郵件及聯絡資料。紀錄已更新但仍未收到時，請聯絡該活動主辦補發。',array['沒收到錄取通知','沒有收到通知怎麼辦？','沒收到通知','錄取通知','付款通知','行前通知'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_078',1,'support','收不到付款通知','先到「我的報名」確認最新狀態，再檢查垃圾郵件及聯絡資料。紀錄已更新但仍未收到時，請聯絡該活動主辦補發。',array['收不到付款通知','沒有收到通知怎麼辦？','沒收到通知','錄取通知','付款通知','行前通知'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
