  ('consumer_faq_080',1,'support','通知寄到錯的信箱怎麼辦？','先到「我的報名」確認最新狀態，再檢查垃圾郵件及聯絡資料。紀錄已更新但仍未收到時，請聯絡該活動主辦補發。',array['通知寄到錯的信箱怎麼辦？','沒有收到通知怎麼辦？','沒收到通知','錄取通知','付款通知','行前通知'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_081',1,'workflow','到現場要出示什麼？','活動當天先打開「我的報名」找到該場紀錄，依最新行前通知出示報名、位置或 QR／核銷資訊。沒有本人報到按鈕時，由現場工作人員核對。',array['到現場要出示什麼？','活動當天怎麼報到？','現場報到','QR','核銷','報到按鈕'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
  ('consumer_faq_082',1,'workflow','QR 報到在哪裡？','活動當天先打開「我的報名」找到該場紀錄，依最新行前通知出示報名、位置或 QR／核銷資訊。沒有本人報到按鈕時，由現場工作人員核對。',array['QR 報到在哪裡？','活動當天怎麼報到？','現場報到','QR','核銷','報到按鈕'],'approved_answer','DOING 報名者 100 題操作情境驗收 v5','published',true,'consumer_faq_seed_v5','platform_super_admin',now()),
